on conflict (slug) do update set title=excluded.title,description=excluded.description,position=excluded.position,is_published=excluded.is_published;

on conflict (set_id, korean) do update set romanization=excluded.romanization,translation_ru=excluded.translation_ru,translation_kk=excluded.translation_kk,example_korean=excluded.example_korean,example_translation_ru=excluded.example_translation_ru,position=excluded.position;
